    const day = parts.find((p2) => p2.type === "day")?.value || "01";
    const hour = parts.find((p2) => p2.type === "hour")?.value || "00";
    const minute = parts.find((p2) => p2.type === "minute")?.value || "00";
    const localDateStr = `${year}-${month}-${day}`;
